// Свой атрибут — обычный класс-наследник Attribute
public class RouteAttribute : Attribute
{
    public RouteAttribute(string path) => Path = path;
    public string Path { get; }       // позиционный аргумент
    public int Order { get; set; }    // именованный аргумент
}

[Route("/orders", Order = 2)]   // суффикс Attribute можно не писать
public class OrdersController { }

